<?php
require_once __DIR__.'/../config/auth.php';require_role('kasir');$pdo=db();$shift=current_shift();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['open'])&&!$shift){$cash=max(0,(float)$_POST['opening_cash']);$pdo->prepare("INSERT INTO cash_shifts(branch_id,cashier_id,opening_cash,status) VALUES(?,?,?,'open')")->execute([branch_id(),user()['id'],$cash]);$id=(int)$pdo->lastInsertId();audit_log('shift_open','cash_shift',$id,[],['opening_cash'=>$cash]);flash('success','Shift berhasil dibuka.');}elseif(isset($_POST['close'])&&$shift){$s=$pdo->prepare("SELECT COALESCE(SUM(t.total),0) FROM transactions t JOIN payments p ON p.transaction_id=t.id WHERE t.shift_id=? AND t.status='paid' AND p.method='tunai'");$s->execute([$shift['id']]);$cashSales=(float)$s->fetchColumn();$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) FROM cash_movements WHERE branch_id=? AND movement_date BETWEEN DATE(?) AND CURDATE()");$s->execute([branch_id(),$shift['opened_at']]);$flow=(float)$s->fetchColumn();$expected=(float)$shift['opening_cash']+$cashSales+$flow;$actual=max(0,(float)$_POST['closing_cash']);$diff=$actual-$expected;$pdo->prepare("UPDATE cash_shifts SET closing_cash=?,expected_cash=?,difference=?,status='closed',closed_at=NOW(),notes=? WHERE id=? AND status='open'")->execute([$actual,$expected,$diff,trim($_POST['notes']),$shift['id']]);audit_log('shift_close','cash_shift',(int)$shift['id'],[],['expected'=>$expected,'actual'=>$actual,'difference'=>$diff]);flash('success','Shift ditutup. Selisih '.rupiah($diff).'.');}redirect('/kasir/shift.php');}
$shift=current_shift();$pageTitle='Shift Kasir';$active='shift';include __DIR__.'/../includes/header.php';?>
<section class="card" style="max-width:650px;margin:auto"><?php if(!$shift):?><h2>Buka shift</h2><p class="muted">Masukkan uang tunai awal di laci kas sebelum mulai berjualan.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Modal kas awal<input type="number" name="opening_cash" min="0" required value="0"></label><button class="btn primary wide" name="open" style="margin-top:16px">Buka Shift</button></form><?php else:?><span class="badge">Shift aktif</span><h2 style="margin-top:12px">Dibuka <?=date('d/m/Y H:i',strtotime($shift['opened_at']))?></h2><p>Modal awal: <strong><?=rupiah($shift['opening_cash'])?></strong></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Uang tunai aktual di laci<input type="number" name="closing_cash" min="0" required></label><label style="margin-top:12px">Catatan<input name="notes" placeholder="Opsional"></label><button class="btn danger wide" name="close" style="margin-top:16px">Tutup Shift & Hitung Selisih</button></form><?php endif;?></section><?php include __DIR__.'/../includes/footer.php';?>
